// 79_mila_deep_check.mjs
// Visit 4326 (Mila May 13) is missing entity_source_links. Need to know:
// - Does Jobber have a visit for Mila on May 13?
// - Is there a Jobber visit with our DB visit_id 4326 anywhere in raw?
// - Was 4326 generated by something other than the Jobber webhook?

import 'dotenv/config';
const PAT = process.env.SUPABASE_PAT;
const PROD = process.env.SUPABASE_PROJECT_ID;
async function pg(sql) {
  const r = await fetch(`https://api.supabase.com/v1/projects/${PROD}/database/query`, {
    method:'POST', headers:{Authorization:`Bearer ${PAT}`,'Content-Type':'application/json'},
    body:JSON.stringify({query:sql}),
  });
  const body = await r.text();
  if (r.status >= 300) throw new Error(`PG ${r.status}: ${body.slice(0, 600)}`);
  return JSON.parse(body);
}
const banner = (s) => console.log(`\n${'='.repeat(70)}\n${s}\n${'='.repeat(70)}`);

banner('A. Visit 4326 full row');
console.log(await pg(`
  SELECT v.id, v.visit_date, v.start_at, v.end_at, v.completed_at,
         v.title, v.visit_status, v.service_type, v.source,
         v.created_at, v.updated_at, v.invoice_id,
         c.id AS client_id, c.client_code, c.name
  FROM public.visits v
  JOIN public.clients c ON c.id = v.client_id
  WHERE v.id = 4326;
`));

banner('B. All Mila entity_source_links (multiple Jobber clients?)');
console.log(await pg(`
  SELECT esl.id, esl.entity_id, esl.source_system, esl.source_id, esl.synced_at
  FROM public.entity_source_links esl
  WHERE esl.entity_type='client' AND esl.entity_id=298
  ORDER BY esl.synced_at;
`));

banner('C. Any Jobber raw visit dated 2026-05-13 with "Mila" in title?');
console.log(await pg(`
  SELECT id, data->>'id' AS jobber_visit_gid,
         data->>'title' AS title,
         data->>'startAt' AS start_at,
         data->>'visitStatus' AS status,
         data->'client'->>'id' AS jobber_client_gid
  FROM raw.jobber_pull_visits
  WHERE (data->>'startAt')::timestamptz >= '2026-05-12'
    AND (data->>'startAt')::timestamptz < '2026-05-15'
    AND data->>'title' ILIKE '%Mila%';
`));

banner('D. ALL Jobber raw visits for Mila in May 2026 (by title)');
console.log(await pg(`
  SELECT id, data->>'id' AS jobber_visit_gid,
         data->>'title' AS title,
         data->>'startAt' AS start_at,
         data->>'visitStatus' AS status,
         data->'client'->>'id' AS jobber_client_gid
  FROM raw.jobber_pull_visits
  WHERE (data->>'startAt')::timestamptz >= '2026-05-01'
    AND (data->>'startAt')::timestamptz < '2026-06-01'
    AND data->>'title' ILIKE '%Mila%'
  ORDER BY (data->>'startAt')::timestamptz;
`));

banner('E. ALL Jobber raw visits for Mila ANY month, by client gid');
console.log(await pg(`
  SELECT id, data->>'id' AS jobber_visit_gid,
         data->>'title' AS title,
         data->>'startAt' AS start_at,
         data->'client'->>'id' AS jobber_client_gid
  FROM raw.jobber_pull_visits
  WHERE data->'client'->>'id' = 'Z2lkOi8vSm9iYmVyL0NsaWVudC85OTU5MzY5OQ=='
  ORDER BY (data->>'startAt')::timestamptz DESC
  LIMIT 10;
`));
